#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAXN = 2e5 + 5;

struct Edge {
    int u, v, w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
} e[MAXN];

struct Query {
    int q, id;
    bool operator<(const Query& other) const {
        return q < other.q;
    }
} qry[MAXN];

int parent[MAXN], sz[MAXN];
ll ans[MAXN];

int find(int x) {
    return parent[x] == x ? x : parent[x] = find(parent[x]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    for (int i = 1; i < n; i++) {
        cin >> e[i].u >> e[i].v >> e[i].w;
    }

    for (int i = 0; i < m; i++) {
        cin >> qry[i].q;
        qry[i].id = i;
    }

    sort(e + 1, e + n);
    sort(qry, qry + m);

    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        sz[i] = 1;
    }

    ll total = 0;
    int edgeIdx = 1;

    for (int i = 0; i < m; i++) {
        int limit = qry[i].q;
        while (edgeIdx < n && e[edgeIdx].w <= limit) {
            int u = find(e[edgeIdx].u);
            int v = find(e[edgeIdx].v);
            if (u != v) {
                total -= (ll)sz[u] * (sz[u] - 1) / 2;
                total -= (ll)sz[v] * (sz[v] - 1) / 2;
                parent[u] = v;
                sz[v] += sz[u];
                total += (ll)sz[v] * (sz[v] - 1) / 2;
            }
            edgeIdx++;
        }
        ans[qry[i].id] = total;
    }

    for (int i = 0; i < m; i++) {
        cout << ans[i] << " \n"[i == m - 1];
    }

    return 0;
}

